import json
from pathlib import Path
from fractions import Fraction
U=[]
def frac(n,d):return f'{n}/{d}'
def row(label,d,n=0,other=0,removed=0):
 return dict(label=label,partes=['p']*(n-removed)+['q']*removed+['s']*other+['_']*(d-n-other))
def bars(*rows,title='El mismo entero en cada barra'):
 return dict(tipo='fracciones',titulo=title,barras=list(rows))
def collections(*groups):return dict(tipo='colecciones',grupos=[dict(label=l,cantidad=n) for l,n in groups])
def act(q,ans,solution,visual):return dict(enunciado=q,respuesta_correcta=str(ans),paso_resuelto=solution,visual=visual)
def unit(id,tema,before,title,explanation,hint,acts,steps,skill='cuartos'):
 for i,a in enumerate(acts):
  ans=a['respuesta_correcta']
  if '/' in ans:
   n,d=map(int,ans.split('/'));opts=[ans,frac(n+1,d),frac(n-1 if n else 2,d)]
  else:
   n=int(ans);opts=[ans,str(n+1),str(n-1 if n else 2)]
  assert len({Fraction(x) for x in opts})==3
  k=i%3;a['opciones']=opts[k:]+opts[:k];a['id']=id+'-v'+str(i+1)
 U.append(dict(id=id,tema=tema,antes_de=before,titulo=title,explicacion=explanation,ejemplo=acts[0]['paso_resuelto'],pasos=steps,pista=hint,visual=acts[0]['visual'],habilidad_concreta=skill,actividades=acts))
tc='fracciones_concepto';to='fracciones_operaciones';tr='fracciones_del_resto'
unit('fr24_mitad',tc,'frac_con_3_unidad_referencia','La mitad: un grupo de dos iguales','Todas las fichas juntas son el total. Para hallar la mitad, hacemos dos grupos iguales y tomamos uno. No necesitamos recordar una tabla.','Repartí una ficha a cada grupo por turno. Contá las de un solo grupo.',[
 act(f'Repartimos {n} fichas en dos grupos iguales. ¿Cuántas hay en una mitad?',n//2,f'Quedan {n//2} fichas en cada grupo. Una mitad tiene {n//2}.',collections(('Grupo 1',n//2),('Grupo 2',n//2))) for n in [8,6,4,10,12,14]],['El total son 8 fichas.','Hacemos dos grupos de 4. Tomamos uno: la mitad es 4.'],'repartir')
unit('fr24_equivalencia',tc,'frac_con_4_equivalencias_visuales','Cortar otra vez sin agregar','Las dos barras representan el mismo entero. Cortamos cada parte en dos, sin agregar ni quitar nada. La zona rayada ocupa lo mismo, aunque ahora tenga más partes.','Compará hasta dónde llega la zona rayada. Contá las partes con los nuevos cortes.',[
 act(f'La barra tenía {n}/{d} rayado. Cortamos cada parte en dos. ¿Qué fracción queda rayada ahora?',frac(n*2,d*2),f'Había {n} de {d} partes. Ahora hay {n*2} de {d*2}: {n}/{d} = {n*2}/{d*2}. La cantidad no cambió.',bars(row('Antes',d,n),row('Más cortes',d*2,n*2))) for n,d in [(1,2),(1,3),(2,3),(1,4),(3,4),(2,5)]],['Antes había una mitad rayada.','Cada mitad se corta en dos. La misma zona ocupa dos cuartos.'])
unit('fr24_reagrupar',tc,'prof_frac_simplificar','Juntar partes sin cambiar la cantidad','Podemos juntar de a dos las partes pequeñas. Cambia la forma de contar, pero la zona rayada sigue ocupando lo mismo.','Mirá los nuevos grupos de dos partes. Contá cuántos quedan rayados.',[
 act(f'Juntamos de a dos las partes de {n}/{d}. ¿Qué fracción muestra la barra de abajo?',frac(n//2,d//2),f'{n} partes rayadas forman {n//2} grupos de dos. Las {d} partes forman {d//2} grupos. Queda {n//2}/{d//2}.',bars(row('Antes',d,n),row('Agrupamos',d//2,n//2))) for n,d in [(2,4),(2,6),(4,6),(2,8),(6,8),(4,10)]],['Dos cuartos rayados se juntan en una mitad.','El entero pasa de cuatro partes a dos: 2/4 = 1/2.'])
unit('fr24_enteros',tc,'prof_frac_clasificar','Juntar partes para formar enteros','Cada barra completa es un entero. Si cada entero tiene cuatro cuartos, ocho cuartos llenan dos barras. Contamos grupos de cuatro, no multiplicamos ocho por cuatro.','Contá cuántas barras completas se llenan. Cada barra representa un entero.',[
 act(f'Cada entero tiene {d} partes iguales. Tenemos {d*k}/{d}. ¿Cuántos enteros completos se forman?',k,f'Formamos {k} grupos de {d} partes. Cada grupo es un entero: {d*k}/{d} = {k}.',bars(*[row('Entero '+str(i+1),d,d) for i in range(k)],title='Cada barra completa es un entero')) for d,k in [(4,2),(3,2),(2,2),(3,3),(4,3),(2,3)]],['Cuatro cuartos llenan una barra.','Otros cuatro cuartos llenan otra: ocho cuartos son dos enteros.'],'grupos')
unit('fr24_sumar',to,'frac_op_1_igual_denominador','Juntar partes del mismo entero','Juntamos partes que tienen el mismo tamaño y pertenecen al mismo entero. Contamos las rayadas. No cambia la cantidad de partes en que dividimos el entero.','Contá todas las partes rayadas. Abajo sigue el número de partes del entero.',[
 act(f'Del mismo entero juntamos {a}/{d} y {b}/{d}. ¿Qué fracción queda rayada?',frac(a+b,d),f'Juntamos {a} + {b} = {a+b} partes. El entero sigue dividido en {d}: queda {a+b}/{d}.',bars(row('Juntamos',d,a,other=b))) for a,b,d in [(1,1,4),(1,2,5),(2,1,6),(2,2,6),(1,3,8),(2,3,8)]],['Juntamos un cuarto y otro cuarto: dos partes.','El entero sigue teniendo cuatro partes: quedan 2/4.'])
unit('fr24_restar',to,'frac_op_1_igual_denominador','Quitar partes del mismo tamaño','Las partes tachadas se quitaron. Contamos las rayadas que siguen sin tachar. El entero de referencia mantiene el mismo tamaño y los mismos cortes.','No cuentes las partes tachadas. Conservá abajo el número de partes del entero.',[
 act(f'Había {a}/{d}. Quitamos {b}/{d}, que está tachado. ¿Qué fracción queda?',frac(a-b,d),f'De {a} partes quitamos {b}: quedan {a-b}. El entero tiene {d} partes, así que queda {a-b}/{d}.',bars(row('Quitamos',d,a,removed=b))) for a,b,d in [(3,1,4),(4,1,5),(4,2,6),(5,2,6),(6,3,8),(7,2,8)]],['Había tres cuartos y tachamos uno.','Quedan dos partes de cuatro: 2/4.'])
unit('fr24_comunes',to,'prof_op_preparar','Cambiar los cortes para poder juntar','Una mitad y un cuarto tienen tamaños distintos. Podemos cortar la mitad en dos cuartos. Así contamos partes del mismo tamaño sin cambiar la cantidad.','La zona rayada no cambia. Contá cuántas partes nuevas ocupa.',[
 act(f'Ahora usamos partes de tamaño 1/{target}. ¿Cómo escribimos {n}/{d} con esos cortes?',frac(n*(target//d),target),f'Cada parte anterior se divide en {target//d}. Las {n} partes ocupan {n*(target//d)} de las {target}: {n*(target//d)}/{target}.',bars(row('Antes',d,n),row('Misma zona',target,n*(target//d)))) for n,d,target in [(1,2,4),(1,3,6),(1,2,6),(3,4,8),(2,3,12),(1,4,12)]],['Una mitad ocupa dos de los cuatro cuartos.','Escribimos 1/2 como 2/4. La cantidad sigue siendo la misma.'])
unit('fr24_sumadistinta',to,'prof_op_preparar','Primero igualar, después juntar','Primero hacemos cortes que sirvan para las dos fracciones. Después juntamos las partes. Las barras representan el mismo entero en todos los pasos.','Usá los cortes de la barra de abajo. Contá juntas sus partes rayadas.',[
 act(f'Del mismo entero sumamos {a}/{d} y 1/{d*k}. El dibujo ya muestra partes iguales. ¿Qué fracción forman juntas?',frac(a*k+1,d*k),f'{a}/{d} ocupa {a*k}/{d*k}. Juntamos {a*k} partes y una más: {a*k+1}/{d*k}.',bars(row('Primera parte',d,a),row('Juntamos',d*k,a*k,other=1))) for a,d,k in [(1,2,2),(1,3,2),(2,3,2),(1,4,2),(1,2,3),(1,3,3)]],['Una mitad se puede contar como dos cuartos.','Juntamos esos dos cuartos con otro: quedan tres cuartos.'])
unit('fr24_restadistinta',to,'prof_op_restar','Igualar los cortes antes de quitar','Para quitar partes, primero las contamos con el mismo tamaño. Después tachamos las que quitamos. El entero completo sigue siendo nuestra referencia.','En la barra de abajo, contá las rayadas que no están tachadas.',[
 act(f'Tenemos {a}/{d} y quitamos 1/{d*k}. Usando los cortes del dibujo, ¿qué fracción queda?',frac(a*k-1,d*k),f'{a}/{d} ocupa {a*k}/{d*k}. Quitamos una parte: quedan {a*k-1}/{d*k}.',bars(row('Había',d,a),row('Quitamos',d*k,a*k,removed=1))) for a,d,k in [(1,2,2),(2,3,2),(3,4,2),(1,2,3),(2,3,3),(3,4,3)]],['Una mitad son dos cuartos.','Tachamos un cuarto: queda un cuarto.'])
unit('fr24_cantidad',to,'frac_op_3_fraccion_cantidad','Tomar algunos grupos de fichas','El entero es toda la colección. La repartimos en grupos iguales. Una fracción nos dice cuántos de esos grupos tomamos.','Cada fila es un grupo. Contá las fichas de las filas marcadas.',[
 act(f'Repartimos {d*size} fichas en {d} grupos iguales. Tomamos {n} grupos: {n}/{d} del total. ¿Cuántas fichas tomamos?',n*size,f'Cada grupo tiene {size} fichas. Tomamos {n} grupos: '+ ' + '.join([str(size)]*n)+f' = {n*size}.',dict(tipo='arreglo',filas=d,columnas=size,seleccionadas=n)) for n,d,size in [(2,3,2),(1,2,3),(3,4,2),(2,3,3),(2,4,3),(3,4,3)]],['Las seis fichas se reparten en tres grupos de dos.','Tomamos dos grupos: 2 + 2 = 4 fichas.'],'repartir')
unit('fr24_partedeparte',to,'frac_op_4_multiplicacion','Tomar la mitad de una parte','Primero marcamos una parte del entero. Después tomamos la mitad de esa zona. Para nombrar el resultado, volvemos a mirar la barra completa del comienzo.','Dividí la zona rayada en dos. Tomá una mitad y comparala con el entero completo.',[
 act(f'Tomamos la mitad de 1/{d} de una barra. ¿Qué fracción del entero original queda rayada abajo?',frac(1,d*2),f'Cada una de las {d} partes se corta en dos: hay {d*2} partes iguales. La mitad de 1/{d} ocupa una: 1/{d*2}.',bars(row('Primero',d,1),row('Tomamos',d*2,1))) for d in [2,3,4,5,6,8]],['Marcamos una mitad de la barra.','Tomamos la mitad de esa zona: es una de cuatro partes del entero, 1/4.'])
unit('fr24_caben',to,'prof_op_dividir_medida','Contar cuántas porciones caben','Dividir también puede preguntar cuántas porciones caben en lo que tenemos. Cada parte rayada es una porción. Primero las contamos en el dibujo.','Cada parte rayada es una porción del tamaño pedido. Contá cuántas hay.',[
 act(f'Tenemos {n}/{d} de barra. Cada porción mide 1/{d} de barra. ¿Cuántas porciones completas podemos dar?',n,f'Hay {n} partes rayadas y cada una mide 1/{d}. Podemos dar {n} porciones: {n}/{d} ÷ 1/{d} = {n}.',bars(row('Disponible',d,n))) for n,d in [(3,4),(2,3),(4,5),(3,6),(5,6),(6,8)]],['Tenemos tres cuartos de una barra.','Cada cuarto es una porción. Contamos tres porciones.'],'grupos')
unit('fr24_resto',tr,'mat_resto_entero','Separar lo usado de lo que queda','El resto es lo que queda después de usar una parte. Las fichas usadas van aparte. Contamos las que todavía tenemos.','Mirá el grupo que dice Quedan. No vuelvas a contar las usadas.',[
 act(f'Teníamos {total} fichas y usamos 1/{d}, que son {total//d}. ¿Cuántas fichas quedan?',total-total//d,f'Usamos {total//d}. De las {total} quedan {total} − {total//d} = {total-total//d}.',collections(('Usadas',total//d),('Quedan',total-total//d))) for total,d in [(8,4),(6,3),(8,2),(12,3),(12,4),(10,5)]],['De ocho fichas usamos dos.','Las otras seis quedan: ese es el resto.'],'quitar')
vals=[(8,2),(12,4),(9,3),(10,2),(16,4),(15,5)]
unit('fr24_referencia',tr,'mat_resto_nuevo_total','Del resto: cambia la cantidad de referencia','Si dice «la mitad del resto», miramos solo lo que quedó. Las fichas usadas ya no están disponibles. El total inicial sirve para contar qué pasó antes.','Para la segunda etapa, buscá cuánto quedó después de usar la primera parte.',[
 act(f'Había {total} fichas. Ya usamos {used}. Ahora piden la mitad del resto. ¿Qué cantidad debemos repartir en dos?',total-used,f'Quedan {total-used} fichas. La mitad del resto se calcula sobre esas {total-used}, no sobre las {total} iniciales.',collections(('Ya usadas',used),('Quedan',total-used))) for total,used in vals],['Había ocho fichas y usamos dos: quedan seis.','Para buscar la mitad del resto, repartimos las seis que quedan.'],'repartir')
unit('fr24_mitaddelresto',tr,'mat_resto_nuevo_total','La mitad de lo que quedó','Primero separamos lo usado. Después repartimos el resto en dos grupos iguales y tomamos uno. Esa es la mitad del resto.','Dejá las usadas aparte. Contá solo las fichas de una mitad del resto.',[
 act(f'De {total} fichas ya usamos {used}. El resto está repartido en dos grupos iguales. ¿Cuántas fichas tiene una mitad del resto?',(total-used)//2,f'Quedan {total-used}. Las repartimos en dos grupos de {(total-used)//2}. En esta segunda etapa tomamos {(total-used)//2} fichas.',collections(('Ya usadas',used),('Mitad 1',(total-used)//2),('Mitad 2',(total-used)//2))) for total,used in vals],['De ocho fichas, dos ya se usaron. Quedan seis.','Repartimos las seis: tres y tres. La mitad del resto es tres.'],'repartir')
